function validate([grid]) {
  const m = grid.length;
  if (m < 1) return 'grid needs at least one row.';
  const n = grid[0].length;
  if (n < 1) return 'Each row needs at least one cell.';
  if (m * n > 200000) return 'grid has at most 2 * 10^5 cells.';
  for (const line of grid) {
    if (line.length !== n) return 'Every row needs the same length.';
    if (line.some(v => v !== 0 && v !== 1)) return 'Each cell is 0 or 1.';
  }
  return null;
}

