function minFlips(grid) {
  const m = grid.length;
  const n = grid[0].length;
  let rowFlips = 0;
  for (let row = 0; row < m; row++) {
    let left = 0;
    let right = n - 1;
    while (left < right) {
      if (grid[row][left] !== grid[row][right]) {
        rowFlips++;
      }
      left++;
      right--;
    }
  }
  let colFlips = 0;
  for (let col = 0; col < n; col++) {
    let top = 0;
    let bottom = m - 1;
    while (top < bottom) {
      if (grid[top][col] !== grid[bottom][col]) {
        colFlips++;
      }
      top++;
      bottom--;
    }
  }
  return Math.min(rowFlips, colFlips);
}

