function minFlips(grid) {
  // Compare each line with its reversed copy; every mismatched pair shows up twice and needs one flip.
  const flips = lines => {
    let total = 0;
    for (const line of lines) {
      const mirrored = [...line].reverse();
      let differ = 0;
      for (let k = 0; k < line.length; k++) if (line[k] !== mirrored[k]) differ++;
      total += differ / 2;
    }
    return total;
  };
  const columns = grid[0].map((_, col) => grid.map(line => line[col]));
  return Math.min(flips(grid), flips(columns));
}

