function generate(rand, size) {
  const pick = (low, high) => low + Math.floor(rand() * (high - low + 1));
  const m = size === 'large' ? pick(80, 100) : pick(1, 6);
  const n = size === 'large' ? pick(80, 100) : pick(1, 6);
  const density = rand();
  const grid = Array.from({ length: m }, () => Array.from({ length: n }, () => (rand() < density ? 1 : 0)));
  // Sometimes make every row (or every column) a palindrome, then disturb a few cells.
  const shape = rand() * (size === 'large' ? 1 : 2);
  if (shape < 0.25) {
    for (const line of grid) for (let col = 0; col < n / 2; col++) line[n - 1 - col] = line[col];
  } else if (shape < 0.5) {
    for (let row = 0; row < m / 2; row++) grid[m - 1 - row] = [...grid[row]];
  }
  if (shape < 0.5) {
    for (let k = pick(0, 2); k > 0; k--) {
      const row = pick(0, m - 1);
      const col = pick(0, n - 1);
      grid[row][col] = 1 - grid[row][col];
    }
  }
  return [grid];
}
